-- =====================================================================
-- RutaSur Rent a Car  ·  Oracle  ·  DDL de tablas 
-- Proyecto Final Bases de Datos II
--
-- Estrategia de IDs: Oracle genera impares (1, 3, 5, ...), MySQL genera pares.
--   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1 INCREMENT BY 2)
--   * BY DEFAULT ON NULL: si el INSERT no trae ID (o trae NULL) Oracle asigna uno impar;
--     si el job de recepción trae el ID par que generó MySQL, se respeta tal cual.
--   * No usar GENERATED ALWAYS: eso rechazaría los IDs que llegan por replicación.
--   * Los saltos por la caché de la secuencia son normales (se menciona en el enunciado).
--
-- Ejecutar conectado como el usuario dueño del esquema (no SYS / SYSTEM). -> se menciona en el enunciado
-- Orden: catálogos -> tablas padre -> tablas hijas.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Catálogos (no se replican, se cargan igual en ambos motores)
-- ---------------------------------------------------------------------
CREATE TABLE catalogo_pais (
  codigo_iso  CHAR(2)       CONSTRAINT pk_catalogo_pais PRIMARY KEY,
  nombre_pais VARCHAR2(60)  NOT NULL CONSTRAINT uk_catalogo_pais_nombre UNIQUE
);

CREATE TABLE parametros_replicacion (
  nombre_parametro  VARCHAR2(50)   CONSTRAINT pk_parametros_replicacion PRIMARY KEY,
  valor_numerico    NUMBER(12,4),
  valor_texto       VARCHAR2(100),
  descripcion       VARCHAR2(200)  NOT NULL,
  fecha_vigencia    TIMESTAMP      DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  -- cada parámetro debe tener al menos un valor
  CONSTRAINT ck_parametros_valor CHECK (valor_numerico IS NOT NULL OR valor_texto IS NOT NULL)
);

-- ---------------------------------------------------------------------
-- 1. Clientes
-- ---------------------------------------------------------------------
CREATE TABLE cliente_renta (
  id_cliente            NUMBER(8) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_cliente_renta PRIMARY KEY,
  nombre_completo       VARCHAR2(120) NOT NULL,
  tipo_documento        VARCHAR2(3)   NOT NULL
                        CONSTRAINT ck_cliente_tipo_doc CHECK (tipo_documento IN ('DNI','PAS','RTN')),
  num_documento         VARCHAR2(20)  NOT NULL,
  telefono              VARCHAR2(20),
  correo                VARCHAR2(100),
  pais_origen           CHAR(2)       NOT NULL
                        CONSTRAINT fk_cliente_pais REFERENCES catalogo_pais (codigo_iso),
  licencia_vigente      CHAR(1)       NOT NULL
                        CONSTRAINT ck_cliente_licencia CHECK (licencia_vigente IN ('S','N')),
  fecha_registro        DATE          NOT NULL,   -- hora local (UTC-6)
  -- columnas técnicas
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_cliente_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT uk_cliente_documento UNIQUE (tipo_documento, num_documento)
);

-- ---------------------------------------------------------------------
-- 2. Sucursales   (NUMBER(4): maximo de 9 999 -> casi 5 000 impares para Oracle)
-- ---------------------------------------------------------------------
CREATE TABLE sucursal (
  id_sucursal           NUMBER(4) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_sucursal PRIMARY KEY,
  nombre_sucursal       VARCHAR2(100) NOT NULL,
  ciudad                VARCHAR2(80)  NOT NULL,
  pais                  CHAR(2)       NOT NULL
                        CONSTRAINT fk_sucursal_pais REFERENCES catalogo_pais (codigo_iso),
  tipo_sucursal         VARCHAR2(20)  NOT NULL
                        CONSTRAINT ck_sucursal_tipo CHECK (tipo_sucursal IN ('AEROPUERTO','CIUDAD','PATIO','TALLER')),
  capacidad_vehiculos   NUMBER(4)     NOT NULL
                        CONSTRAINT ck_sucursal_capacidad CHECK (capacidad_vehiculos > 0),
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_sucursal_eliminado CHECK (eliminado IN ('S','N'))
);

-- ---------------------------------------------------------------------
-- 3. Modelos de vehículo
-- ---------------------------------------------------------------------
CREATE TABLE modelo_vehiculo (
  id_modelo             NUMBER(5) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_modelo_vehiculo PRIMARY KEY,
  marca                 VARCHAR2(40)  NOT NULL,
  modelo                VARCHAR2(40)  NOT NULL,
  categoria             VARCHAR2(20)  NOT NULL
                        CONSTRAINT ck_modelo_categoria CHECK (categoria IN ('ECONOMICO','SEDAN','SUV','PICKUP','VAN')),
  capacidad_pasajeros   NUMBER(2)     NOT NULL
                        CONSTRAINT ck_modelo_pasajeros CHECK (capacidad_pasajeros > 0),
  tarifa_diaria         NUMBER(10,2)  NOT NULL
                        CONSTRAINT ck_modelo_tarifa CHECK (tarifa_diaria >= 0),   -- HNL
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_modelo_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT uk_modelo_marca_modelo UNIQUE (marca, modelo)
);

-- ---------------------------------------------------------------------
-- 4. Vehículos
-- ---------------------------------------------------------------------
CREATE TABLE vehiculo (
  id_vehiculo             NUMBER(6) GENERATED BY DEFAULT ON NULL AS IDENTITY
                          (START WITH 1 INCREMENT BY 2)
                          CONSTRAINT pk_vehiculo PRIMARY KEY,
  placa                   VARCHAR2(10)  NOT NULL
                          CONSTRAINT uk_vehiculo_placa UNIQUE
                          CONSTRAINT ck_vehiculo_placa CHECK (REGEXP_LIKE(placa, '^[A-Z]{3}[0-9]{4}$')),
  vin                     VARCHAR2(17)  NOT NULL
                          CONSTRAINT uk_vehiculo_vin UNIQUE
                          CONSTRAINT ck_vehiculo_vin CHECK (LENGTH(vin) = 17),
  id_modelo               NUMBER(5)     NOT NULL
                          CONSTRAINT fk_vehiculo_modelo REFERENCES modelo_vehiculo (id_modelo),
  anio                    NUMBER(4)     NOT NULL
                          CONSTRAINT ck_vehiculo_anio CHECK (anio >= 2000),
  kilometraje             NUMBER(8)     NOT NULL
                          CONSTRAINT ck_vehiculo_km CHECK (kilometraje >= 0),
  transmision_automatica  CHAR(1)       NOT NULL
                          CONSTRAINT ck_vehiculo_transmision CHECK (transmision_automatica IN ('S','N')),
  estado_operacion        VARCHAR2(20)  NOT NULL
                          CONSTRAINT ck_vehiculo_estado CHECK (estado_operacion IN
                            ('DISPONIBLE','RENTADO','MANTENIMIENTO','RETENIDO','BAJA')),
  version_registro        NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc    TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado               CHAR(1)       DEFAULT 'N' NOT NULL
                          CONSTRAINT ck_vehiculo_eliminado CHECK (eliminado IN ('S','N'))
);

-- ---------------------------------------------------------------------
-- 5. Ubicación actual de la flota (un registro por vehículo)
-- ---------------------------------------------------------------------
CREATE TABLE ubicacion_vehiculo (
  id_ubicacion          NUMBER(8) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_ubicacion_vehiculo PRIMARY KEY,
  id_vehiculo           NUMBER(6)     NOT NULL
                        CONSTRAINT uk_ubicacion_vehiculo UNIQUE
                        CONSTRAINT fk_ubicacion_vehiculo REFERENCES vehiculo (id_vehiculo),
  id_sucursal           NUMBER(4)     NOT NULL
                        CONSTRAINT fk_ubicacion_sucursal REFERENCES sucursal (id_sucursal),
  nivel_combustible     NUMBER(3)     NOT NULL
                        CONSTRAINT ck_ubicacion_combustible CHECK (nivel_combustible BETWEEN 0 AND 100),
  fecha_actualizacion   DATE          NOT NULL,   -- hora local
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_ubicacion_eliminado CHECK (eliminado IN ('S','N'))
);

-- ---------------------------------------------------------------------
-- 6. Contratos de renta
-- ---------------------------------------------------------------------
CREATE TABLE contrato_renta (
  id_contrato           NUMBER(8) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_contrato_renta PRIMARY KEY,
  id_cliente            NUMBER(8)     NOT NULL
                        CONSTRAINT fk_contrato_cliente REFERENCES cliente_renta (id_cliente),
  id_vehiculo           NUMBER(6)     NOT NULL
                        CONSTRAINT fk_contrato_vehiculo REFERENCES vehiculo (id_vehiculo),
  sucursal_retiro       NUMBER(4)     NOT NULL
                        CONSTRAINT fk_contrato_suc_retiro REFERENCES sucursal (id_sucursal),
  sucursal_devolucion   NUMBER(4)     NOT NULL
                        CONSTRAINT fk_contrato_suc_devolucion REFERENCES sucursal (id_sucursal),
  fecha_inicio          DATE          NOT NULL,   -- hora local
  fecha_fin             DATE          NOT NULL,   -- hora local
  estado_contrato       VARCHAR2(20)  NOT NULL
                        CONSTRAINT ck_contrato_estado CHECK (estado_contrato IN
                          ('RESERVADO','ACTIVO','FINALIZADO','CANCELADO')),
  prioridad             NUMBER(1)     NOT NULL
                        CONSTRAINT ck_contrato_prioridad CHECK (prioridad BETWEEN 1 AND 3),  -- 1 = alta
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_contrato_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT ck_contrato_fechas CHECK (fecha_fin > fecha_inicio)
);

-- ---------------------------------------------------------------------
-- 7. Facturas
-- ---------------------------------------------------------------------
CREATE TABLE factura (
  id_factura            NUMBER(8) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_factura PRIMARY KEY,
  id_contrato           NUMBER(8)     NOT NULL
                        CONSTRAINT uk_factura_contrato UNIQUE
                        CONSTRAINT fk_factura_contrato REFERENCES contrato_renta (id_contrato),
  fecha_emision         DATE          NOT NULL,   -- hora local
  subtotal              NUMBER(12,2)  NOT NULL CONSTRAINT ck_factura_subtotal CHECK (subtotal >= 0),  -- HNL
  isv                   NUMBER(12,2)  NOT NULL CONSTRAINT ck_factura_isv CHECK (isv >= 0),            -- HNL
  total                 NUMBER(12,2)  NOT NULL,                                                      -- HNL
  observaciones         VARCHAR2(150),
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_factura_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT ck_factura_total CHECK (total = subtotal + isv)
);

-- ---------------------------------------------------------------------
-- 8. Servicios
-- ---------------------------------------------------------------------
CREATE TABLE servicio_renta (
  id_servicio            NUMBER(5) GENERATED BY DEFAULT ON NULL AS IDENTITY
                         (START WITH 1 INCREMENT BY 2)
                         CONSTRAINT pk_servicio_renta PRIMARY KEY,
  descripcion            VARCHAR2(120) NOT NULL,
  costo_diario           NUMBER(10,2)  NOT NULL
                         CONSTRAINT ck_servicio_costo CHECK (costo_diario >= 0),   -- HNL
  requiere_autorizacion  CHAR(1)       NOT NULL
                         CONSTRAINT ck_servicio_autorizacion CHECK (requiere_autorizacion IN ('S','N')),
  tipo_servicio          VARCHAR2(20)  NOT NULL
                         CONSTRAINT ck_servicio_tipo CHECK (tipo_servicio IN
                           ('RENTA','SEGURO','EQUIPO','CONDUCTOR','ENTREGA')),
  version_registro       NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc   TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado              CHAR(1)       DEFAULT 'N' NOT NULL
                         CONSTRAINT ck_servicio_eliminado CHECK (eliminado IN ('S','N'))
);

-- ---------------------------------------------------------------------
-- 9. Detalle de factura  (PK compuesta: no usa generador de ID)
-- ---------------------------------------------------------------------
CREATE TABLE detalle_factura (
  id_factura            NUMBER(8)     NOT NULL
                        CONSTRAINT fk_detalle_factura REFERENCES factura (id_factura),
  id_servicio           NUMBER(5)     NOT NULL
                        CONSTRAINT fk_detalle_servicio REFERENCES servicio_renta (id_servicio),
  dias                  NUMBER(3)     NOT NULL CONSTRAINT ck_detalle_dias CHECK (dias > 0),
  subtotal              NUMBER(12,2)  NOT NULL CONSTRAINT ck_detalle_subtotal CHECK (subtotal >= 0),  -- HNL
  aplica_isv            CHAR(1)       NOT NULL CONSTRAINT ck_detalle_isv CHECK (aplica_isv IN ('S','N')),
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_detalle_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT pk_detalle_factura PRIMARY KEY (id_factura, id_servicio)
);

-- ---------------------------------------------------------------------
-- 10. Traslados de vehículos (historial, nunca se modifica ni elimina)
-- ---------------------------------------------------------------------
CREATE TABLE traslado_vehiculo (
  id_traslado           NUMBER(8) GENERATED BY DEFAULT ON NULL AS IDENTITY
                        (START WITH 1 INCREMENT BY 2)
                        CONSTRAINT pk_traslado_vehiculo PRIMARY KEY,
  id_vehiculo           NUMBER(6)     NOT NULL
                        CONSTRAINT fk_traslado_vehiculo REFERENCES vehiculo (id_vehiculo),
  sucursal_origen       NUMBER(4)     NOT NULL
                        CONSTRAINT fk_traslado_origen REFERENCES sucursal (id_sucursal),
  sucursal_destino      NUMBER(4)     NOT NULL
                        CONSTRAINT fk_traslado_destino REFERENCES sucursal (id_sucursal),
  km_recorridos         NUMBER(6)     NOT NULL CONSTRAINT ck_traslado_km CHECK (km_recorridos > 0),
  motivo                VARCHAR2(25)  NOT NULL
                        CONSTRAINT ck_traslado_motivo CHECK (motivo IN ('REBALANCEO','MANTENIMIENTO','DEVOLUCION')),
  fecha_traslado        DATE          NOT NULL,   -- hora local
  version_registro      NUMBER(10)    DEFAULT 1 NOT NULL,
  fecha_ultima_mod_utc  TIMESTAMP     DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL,
  eliminado             CHAR(1)       DEFAULT 'N' NOT NULL
                        CONSTRAINT ck_traslado_eliminado CHECK (eliminado IN ('S','N')),
  CONSTRAINT ck_traslado_destino CHECK (sucursal_destino <> sucursal_origen)
);
